// Fast O(1) monotonic cursor-based lookup and linear interpolation on ESP32
inline bool imu_get_sample(float t_s, float &out_ax, float &out_ay, float &out_az,
                          float &out_gx, float &out_gy, float &out_gz) {
    static uint16_t imu_cursor = 0;
    if (IMU_DATA_COUNT == 0) return false;

    if (t_s <= IMU_DATA[0].time_s) {
        out_ax = IMU_DATA[0].ax;
        out_ay = IMU_DATA[0].ay;
        out_az = IMU_DATA[0].az;
        out_gx = IMU_DATA[0].gx;
        out_gy = IMU_DATA[0].gy;
        out_gz = IMU_DATA[0].gz;
        return true;
    }

    if (t_s >= IMU_DATA[IMU_DATA_COUNT - 1].time_s) {
        out_ax = IMU_DATA[IMU_DATA_COUNT - 1].ax;
        out_ay = IMU_DATA[IMU_DATA_COUNT - 1].ay;
        out_az = IMU_DATA[IMU_DATA_COUNT - 1].az;
        out_gx = IMU_DATA[IMU_DATA_COUNT - 1].gx;
        out_gy = IMU_DATA[IMU_DATA_COUNT - 1].gy;
        out_gz = IMU_DATA[IMU_DATA_COUNT - 1].gz;
        return false; // Reached end of simulation dataset
    }

    // Advance cursor monotonically in O(1) amortized time
    while (imu_cursor + 1 < IMU_DATA_COUNT && IMU_DATA[imu_cursor + 1].time_s <= t_s) {
        imu_cursor++;
    }
    // Rewind cursor if timestamp went backwards (e.g. restart / reboot)
    while (imu_cursor > 0 && IMU_DATA[imu_cursor].time_s > t_s) {
        imu_cursor--;
    }

    const ImuDataPoint &p0 = IMU_DATA[imu_cursor];
    const ImuDataPoint &p1 = IMU_DATA[imu_cursor + 1];
    float dt = p1.time_s - p0.time_s;
    float factor = (dt > 1e-6f) ? ((t_s - p0.time_s) / dt) : 0.0f;
    if (factor < 0.0f) factor = 0.0f;
    if (factor > 1.0f) factor = 1.0f;

    out_ax = p0.ax + factor * (p1.ax - p0.ax);
    out_ay = p0.ay + factor * (p1.ay - p0.ay);
    out_az = p0.az + factor * (p1.az - p0.az);
    out_gx = p0.gx + factor * (p1.gx - p0.gx);
    out_gy = p0.gy + factor * (p1.gy - p0.gy);
    out_gz = p0.gz + factor * (p1.gz - p0.gz);
    return true;
}

inline bool imu_get_sample(float t_s, ImuDataPoint &out) {
    out.time_s = t_s;
    return imu_get_sample(t_s, out.ax, out.ay, out.az, out.gx, out.gy, out.gz);
}

